import antfu from '@antfu/eslint-config'

export default antfu({
  type: 'lib',
  stylistic: true,
  ignores: [
    '**/fixtures',
    // Vendored verbatim from the official distribution: `lint:fix` must never rewrite it.
    'spec/factur-x-*/**',
    // Generated by docs/scripts/gen-models.mjs, ignored in docs/.gitignore.
    'docs/api/models',
    // ...globs
  ],
})
  // Runnable scripts (example snippets embedded into the docs, consumer smoke
  // test): top-level await and console output are intentional.
  .append({
    files: ['examples/**/*.ts', 'tests/compat/**/*.mjs'],
    rules: {
      'antfu/no-top-level-await': 'off',
      'no-console': 'off',
    },
  })
  // Code blocks in the docs are API signatures, not modules: importing
  // `Buffer` in each of them would only add noise.
  .append({
    files: ['**/*.md/**'],
    rules: {
      'node/prefer-global/buffer': 'off',
    },
  })
  // Shipped code must run on the `engines.node` floor (read from package.json),
  // whatever Node it is developed on. The build lowers syntax to that floor
  // (build.config.ts) but cannot polyfill runtime APIs: flag them here.
  .append({
    files: ['src/**/*.ts'],
    rules: {
      'node/no-unsupported-features/es-builtins': 'error',
      'node/no-unsupported-features/node-builtins': ['error', {
        // Unflagged since 20.11.0 (hence the floor), only marked stable in
        // 22.16 / 24.0, which the rule reports as "experimental".
        ignores: ['import.meta.dirname'],
      }],
    },
  })
